#!/usr/bin/env node
import {
  ExitCode,
  GramCLIError
} from "./chunk-IXNX2GX7.js";

// src/core/ssrf.ts
import { lookup } from "dns/promises";
import { isIP } from "net";
var FORBIDDEN_IPV4_RANGES = [
  ["0.0.0.0", 8],
  // "this network"
  ["10.0.0.0", 8],
  // RFC1918 private
  ["100.64.0.0", 10],
  // carrier-grade NAT
  ["127.0.0.0", 8],
  // loopback
  ["169.254.0.0", 16],
  // link-local (cloud metadata lives here)
  ["172.16.0.0", 12],
  // RFC1918 private
  ["192.0.0.0", 24],
  // IETF protocol assignments
  ["192.168.0.0", 16],
  // RFC1918 private
  ["198.18.0.0", 15],
  // benchmarking
  ["224.0.0.0", 4]
  // multicast
];
function ipv4ToInt(ip) {
  return ip.split(".").reduce((acc, octet) => (acc << 8) + Number(octet), 0) >>> 0;
}
function isForbiddenIPv4(ip) {
  const target = ipv4ToInt(ip);
  return FORBIDDEN_IPV4_RANGES.some(([base, bits]) => {
    const mask = bits === 0 ? 0 : ~0 << 32 - bits >>> 0;
    return (target & mask) === (ipv4ToInt(base) & mask);
  });
}
function hexGroupsToIPv4(a, b) {
  const av = parseInt(a, 16);
  const bv = parseInt(b, 16);
  return [av >> 8, av & 255, bv >> 8, bv & 255].join(".");
}
function isForbiddenIPv6(ip) {
  const normalized = ip.toLowerCase();
  if (normalized === "::1" || normalized === "::") return true;
  if (normalized.startsWith("fe80:")) return true;
  if (normalized.startsWith("fc") || normalized.startsWith("fd")) return true;
  const dotted = normalized.match(/^::ffff:(\d+\.\d+\.\d+\.\d+)$/);
  if (dotted?.[1]) return isForbiddenIPv4(dotted[1]);
  const hex = normalized.match(/^::ffff:([0-9a-f]{1,4}):([0-9a-f]{1,4})$/);
  if (hex?.[1] && hex[2]) {
    return isForbiddenIPv4(hexGroupsToIPv4(hex[1], hex[2]));
  }
  return false;
}
async function assertPublicUrl(url) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    throw new GramCLIError(`Invalid URL: ${url}`, ExitCode.Error);
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new GramCLIError(
      `Refusing to fetch ${url}: only http/https URLs are allowed.`,
      ExitCode.Error
    );
  }
  const hostname = parsed.hostname.replace(/^\[|\]$/g, "");
  if (hostname.toLowerCase() === "localhost") {
    throw new GramCLIError(
      `Refusing to fetch ${url}: localhost is not a public address.`,
      ExitCode.Error
    );
  }
  const literalFamily = isIP(hostname);
  let addresses;
  if (literalFamily) {
    addresses = [{ address: hostname, family: literalFamily }];
  } else {
    try {
      addresses = await lookup(hostname, { all: true });
    } catch {
      throw new GramCLIError(
        `Could not resolve host: ${hostname}`,
        ExitCode.Error
      );
    }
  }
  for (const { address, family } of addresses) {
    const forbidden = family === 6 ? isForbiddenIPv6(address) : isForbiddenIPv4(address);
    if (forbidden) {
      throw new GramCLIError(
        `Refusing to fetch ${url}: resolves to ${address}, which is not a public address.`,
        ExitCode.Error
      );
    }
  }
}

// src/core/http.ts
var FETCH_TIMEOUT_MS = 15e3;
var MAX_RESPONSE_BYTES = 10 * 1024 * 1024;
var MAX_REDIRECTS = 5;
async function fetchWithSsrfGuard(url) {
  let currentUrl = url;
  for (let i = 0; i <= MAX_REDIRECTS; i++) {
    await assertPublicUrl(currentUrl);
    const res = await fetch(currentUrl, {
      signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
      redirect: "manual"
    });
    if (res.status >= 300 && res.status < 400) {
      const location = res.headers.get("location");
      if (!location) {
        throw new GramCLIError(
          `Redirect from ${currentUrl} had no Location header.`,
          ExitCode.Error
        );
      }
      currentUrl = new URL(location, currentUrl).toString();
      continue;
    }
    return res;
  }
  throw new GramCLIError(
    `Too many redirects (> ${MAX_REDIRECTS}) fetching ${url}.`,
    ExitCode.Error
  );
}
async function readBodyWithLimit(res) {
  const reader = res.body?.getReader();
  if (!reader) return res.text();
  const decoder = new TextDecoder();
  let result = "";
  let received = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    received += value.byteLength;
    if (received > MAX_RESPONSE_BYTES) {
      await reader.cancel();
      throw new GramCLIError(
        `Response exceeds the ${MAX_RESPONSE_BYTES / (1024 * 1024)}MB limit.`,
        ExitCode.Error
      );
    }
    result += decoder.decode(value, { stream: true });
  }
  result += decoder.decode();
  return result;
}
async function fetchTextWithSsrfGuard(url) {
  try {
    const res = await fetchWithSsrfGuard(url);
    if (!res.ok) {
      throw new GramCLIError(
        `HTTP ${res.status} fetching ${url}`,
        ExitCode.Error
      );
    }
    return {
      body: await readBodyWithLimit(res),
      contentType: res.headers.get("content-type") ?? ""
    };
  } catch (err) {
    if (err instanceof Error && err.name === "TimeoutError") {
      throw new GramCLIError(
        `Timed out fetching ${url} after ${FETCH_TIMEOUT_MS / 1e3}s.`,
        ExitCode.Error
      );
    }
    throw err;
  }
}

export {
  fetchTextWithSsrfGuard
};
